import 'package:flutter/material.dart';
import 'package:tuple/tuple.dart';

import '../../../../l10n/l10n.dart';
import '../../../../themes/stack_colors.dart';
import '../../../../utilities/enums/add_wallet_type_enum.dart';
import '../../../../utilities/text_styles.dart';
import '../../../../wallets/crypto_currency/crypto_currency.dart';
import '../../name_your_wallet_view/name_your_wallet_view.dart';

class CreateWalletButtonGroup extends StatelessWidget {
  const CreateWalletButtonGroup({
    super.key,
    required this.coin,
    required this.isDesktop,
  });

  final CryptoCurrency coin;
  final bool isDesktop;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: isDesktop
          ? CrossAxisAlignment.center
          : CrossAxisAlignment.stretch,
      children: [
        ConstrainedBox(
          constraints: BoxConstraints(
            minHeight: isDesktop ? 70 : 0,
            minWidth: isDesktop ? 480 : 0,
          ),
          child: TextButton(
            style: Theme.of(context)
                .extension<StackColors>()!
                .getPrimaryEnabledButtonStyle(context),
            onPressed: () {
              // Root navigator: on desktop this can sit in the wallet
              // list's nested navigator.
              Navigator.of(context, rootNavigator: isDesktop).pushNamed(
                NameYourWalletView.routeName,
                arguments: Tuple2(AddWalletType.New, coin),
              );
            },
            child: Text(
              l10n.addWalletCreateNew,
              style: isDesktop
                  ? STextStyles.desktopButtonEnabled(context)
                  : STextStyles.button(context),
            ),
          ),
        ),
        SizedBox(height: isDesktop ? 16 : 12),
        ConstrainedBox(
          constraints: BoxConstraints(
            minHeight: isDesktop ? 70 : 0,
            minWidth: isDesktop ? 480 : 0,
          ),
          child: TextButton(
            style: Theme.of(context)
                .extension<StackColors>()!
                .getSecondaryEnabledButtonStyle(context),
            onPressed: () {
              // Root navigator: on desktop this can sit in the wallet
              // list's nested navigator.
              Navigator.of(context, rootNavigator: isDesktop).pushNamed(
                NameYourWalletView.routeName,
                arguments: Tuple2(AddWalletType.Restore, coin),
              );
            },
            child: Text(
              l10n.addWalletRestore,
              style: isDesktop
                  ? STextStyles.desktopButtonSecondaryEnabled(context)
                  : STextStyles.button(context).copyWith(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .accentColorDark,
                    ),
            ),
          ),
        ),
      ],
    );
  }
}
